```
function squareArray(arr) {
  // Initialize an empty array to store the squared numbers
  var squaredArray = [];

  // Iterate through the original array of numbers
  for (var i = 0; i < arr.length; i++) {
    // Square the current number by multiplying it by itself
    var squaredNumber = arr[i] * arr[i];

    // Add the squared number to the empty array
