// Function to find the maximum element in an unsorted array
int maxElement(int arr[], int n) {
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Function to find the minimum element in an unsorted array
int minElement(int arr[], int n) {
    int min = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] < min) {
            min = arr[i];
        }
    }
    return min;
}

// Function to find both the maximum and minimum elements in an unsorted array
int* findMaxAndMin(int arr[], int n) {
    int max = maxElement(arr, n);
    int min = minElement(arr, n);
    return &max;
}

