1. Select a sorting algorithm (e.g. bubble sort, quicksort, mergesort, etc.)
2. Initialize a list of pointers to the elements in the original list
3. Loop through the list of pointers, using the selected sorting algorithm to sort each sublist of pointers
4. Once all sublists are sorted, loop through the list of pointers again and combine the sorted sublists into a single sorted list

Here is an example of how this algorithm might be implemented in Python:
```
def sort_list(list):
    # Select a sorting algorithm
    if len(list) <= 1:
        return list
    elif len(list) == 2:
        # Bubble sort is simple and easy to implement, but it has a high time complexity
        # for small lists, so we'll use quicksort for smaller lists
        return quicksort(list)
    else:
        return mergesort(list)

def bubble_sort(list):
    # Bubble sort algorithm
    n = len(list)
    for i in range(n-1):
        for j in range(0, n-i-1):
            if list[j] > list[j+1]:
                list[j], list[j+1] = list[j+1], list[j]
    return list

def quicksort(list):
    # Quicksort algorithm
    n = len(list)
    if n <= 1:
        return list
    pivot = list[0]
    less = [x for x in list[1:] if x <= pivot]
    greater = [x for x in list[1:] if x > pivot]
    return quicksort(less) + [pivot] + quicksort(greater)

def mergesort(list):
    # Merge sort algorithm
    n = len(list)
    if n <= 1:
        return list
    mid = n // 2
    left = sort(list[:mid])
    right = sort(list[mid:])
    return merge(left, right)

def sort(list):
    # Recursive sorting function
    if len(list) <= 1:
        return list
    else:
        return sort(list[1:]) + [list[0]]

def merge(left, right):
    # Merge two sorted lists
    n1 = len(left)
    n2 = len(right)
    result = []
    i = 0
    j = 0
    while i < n1 and j < n2:
        if left[i] <= right[j]:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    return result + [left[i]] + [right[j]]

# Test the algorithm
list = [4, 2, 7, 3, 1, 6, 5]
print(sort_list(list))
```
This algorithm will sort the list of numbers in ascending order.

It's worth noting that the time complexity of this algorithm is O(n log n) for mergesort and O(n^2) for bubble sort, so mergesort is generally the better choice for larger lists. However, bubble sort can be useful for small lists or for educational purposes.

