```
#include <iostream>

void bubbleSort(int arr[], int n) {
  int i, j, temp;

  // loop through the array n-1 times
  for (i = 0; i < n - 1; i++) {
    // compare adjacent elements and swap if they are in the wrong order
    for (j = 0; j < n - i - 1; j++) {
      if (arr[j] > arr[j + 1]) {
        temp = arr[j];
        arr[j] = arr[j + 1];
        arr[j + 1] = temp;
      }
    }
  }
}

int main() {
  int arr[5] = { 4, 2, 7, 3, 1 };
  int n = sizeof(arr) / sizeof(arr[0]);

