  A linked list is a fundamental data structure in computer science, consisting of a sequence of nodes, each of which contains a value and a reference (or pointer) to the next node in the list. Here is a possible implementation of a linked list in Python:

class Node:
    def __init__(self, value, next=None):
        self.value = value
        self.next = next

class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, value):
        node = Node(value)
        if not self.head:
            self.head = node
        else:
            self.head.next = node
        self.head = node

    def insert(self, index, value):
        if index == 0:
            self.append(value)
        else:
            node = Node(value)
            current = self.head
            while current:
                if index == 0:
                    break
                current = current.next
                index -= 1
            current.next = node
            node.prev = current
            self.head = node

    def remove(self, value):
        current = self.head
        previous = None
        while current:
            if current.value == value:
                if not previous:
                    self.head = current.next
                else:
                    previous.next = current.next
                break
            previous = current
            current = current.next
        return current

    def size(self):
        count = 0
        current = self.head
        while current:
            count += 1
            current = current.next
        return count

    def __len__(self):
        return self.size()

    def __iter__(self):
        current = self.head
        while current:
            yield current.value
            current = current.next

    def __getitem__(self, index):
        if index < 0:
            raise IndexError("List index out of range")
        current = self.head
        count = 0
        while current:
            count += 1
            if count == index:
                return current.value
            current = current.next
        raise IndexError("List index out of range")

    def __setitem__(self, index, value):
        if index < 0:
            raise IndexError("List index out of range")
        current = self.head
        count = 0
        while current:
            count += 1
            if count == index:
                current.value = value
                return
            current = current.next
        raise IndexError("List index out of range")

    def __delitem__(self, index):
        if index < 0:
            raise IndexError("List index out of range")
        current = self.head
        count = 0
        while current:
            count += 1
            if count == index:
                if current.prev:
                    current.prev.next = current.next
                else:
                    self.head = current.next
                break
            current = current.next
        else:
            raise IndexError("List index out of range")

Here is an example of how to use the LinkedList class:

